package com.ryanjei.orushio.pve.map;
import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.domain.MapProfileId;import java.io.*;import java.nio.file.*;import java.util.zip.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class SafeWorldZipImporterTest{@TempDir Path temp;@Test void 直下ワールドを登録する()throws Exception{Path zip=zip("world.zip",new Entry("level.dat","level"),new Entry("region/r.0.0.mca","region"));MapProfile p=importer().importZip(zip,new MapProfileId("map-a"),"マップA");assertTrue(Files.exists(temp.resolve("maps/map-a/template/level.dat")));assertFalse(p.enabled());}@Test void 一階層のワールドを補正する()throws Exception{Path zip=zip("nested.zip",new Entry("map-name/level.dat","level"));importer().importZip(zip,new MapProfileId("nested"),"入れ子");assertTrue(Files.exists(temp.resolve("maps/nested/template/level.dat")));}@Test void zipSlipと絶対パスを拒否する()throws Exception{assertEquals("ZIP_SLIP",assertThrows(MapIoException.class,()->importer().importZip(zip("slip.zip",new Entry("../escape","x")),new MapProfileId("slip"),"x")).code());assertEquals("ZIP_PATH",assertThrows(MapIoException.class,()->importer().importZip(zip("abs.zip",new Entry("C:/escape","x")),new MapProfileId("absolute"),"x")).code());}@Test void シンボリックリンクを拒否する()throws Exception{Path path=zip("symlink.zip",new Entry("level.dat","level"),new Entry("link","target"));byte[] bytes=Files.readAllBytes(path);for(int i=0;i<=bytes.length-46;i++){if(bytes[i]==0x50&&bytes[i+1]==0x4b&&bytes[i+2]==0x01&&bytes[i+3]==0x02){int nameLength=(bytes[i+28]&255)|((bytes[i+29]&255)<<8);String name=new String(bytes,i+46,nameLength);if(name.equals("link")){int mode=0120777;int external=mode<<16;for(int j=0;j<4;j++)bytes[i+38+j]=(byte)(external>>>(8*j));break;}}}Files.write(path,bytes);assertEquals("ZIP_SYMLINK",assertThrows(MapIoException.class,()->importer().importZip(path,new MapProfileId("symlink"),"x")).code());}@Test void 空zipと不正zipとワールド不成立を拒否する()throws Exception{Path empty=temp.resolve("empty.zip");try(var out=new ZipOutputStream(Files.newOutputStream(empty))){}assertEquals("EMPTY_ZIP",assertThrows(MapIoException.class,()->importer().importZip(empty,new MapProfileId("empty"),"x")).code());Path bad=temp.resolve("bad.zip");Files.writeString(bad,"bad");assertThrows(MapIoException.class,()->importer().importZip(bad,new MapProfileId("bad-map"),"x"));assertEquals("WORLD_NOT_FOUND",assertThrows(MapIoException.class,()->importer().importZip(zip("no-world.zip",new Entry("a.txt","x")),new MapProfileId("no-world"),"x")).code());}@Test void 展開サイズとファイル数上限を拒否する()throws Exception{var size=new SafeWorldZipImporter(temp.resolve("maps"),new SafeWorldZipImporter.Limits(10000,3,10));assertEquals("ZIP_EXPANDED_LIMIT",assertThrows(MapIoException.class,()->size.importZip(zip("large.zip",new Entry("level.dat","1234")),new MapProfileId("large"),"x")).code());var count=new SafeWorldZipImporter(temp.resolve("maps"),new SafeWorldZipImporter.Limits(10000,100,1));assertEquals("ZIP_FILE_LIMIT",assertThrows(MapIoException.class,()->count.importZip(zip("many.zip",new Entry("level.dat","x"),new Entry("a","x")),new MapProfileId("many"),"x")).code());}private SafeWorldZipImporter importer(){return new SafeWorldZipImporter(temp.resolve("maps"),new SafeWorldZipImporter.Limits(10000,10000,100));}private Path zip(String name,Entry...entries)throws Exception{Path path=temp.resolve(name);try(var out=new ZipOutputStream(Files.newOutputStream(path))){for(Entry e:entries){out.putNextEntry(new ZipEntry(e.name));out.write(e.value.getBytes());out.closeEntry();}}return path;}private record Entry(String name,String value){} }
